vertices.reserve(polygon_coords.size());

for (const auto& coord : polygon_coords) {
    // Project 2D point to 3D plane
    Kernel::Point_3 point_on_plane = plane.project(Kernel::Point_3(coord[0], coord[1], 0));

    // Insert vertex into triangulation
    Triangulation::Vertex_handle vh = triangulation.insert(point_on_plane, walk_start);
    vertices.push_back(vh);
}

// Insert constraints (edges between consecutive vertices)
for (size_t i = 0; i < vertices.size(); ++i) {
    size_t j = (i + 1) % vertices.size(); // Connect last to first to close the polygon
    triangulation.insert_constraint(vertices[i], vertices[j]);
}

